import { HardeningBenchmarks } from '../components/HardeningBenchmarks';
import { ComparisonBenchmarks } from '../components/ComparisonBenchmarks';
import { QueueBenchmarks } from '../components/QueueBenchmarks';
import { AdaptationBenchmarks } from '../components/AdaptationBenchmarks';
import { PoolBalanceBenchmarks } from '../components/PoolBalanceBenchmarks';
import { OperationBenchmarks } from '../components/OperationBenchmarks';
import { ResourceBenchmarks } from '../components/ResourceBenchmarks';
import { useEffect, useState } from 'react';
import data from '../data/commerce.json';
import validation from '../data/controller-validation.json';
import tenants from '../data/tenants.json';
import priority from '../data/priority.json';
import sharing from '../data/sharing.json';
import decisions from '../data/decisions-benchmark.json';
import { Button, CodeBlock, ImageFigure, Note, PageTitle, Section, Table, Tabs } from '../components/ui';
const n = (value: number | null, digits = 1) => value === null ? 'No successful samples' : value.toFixed(digits);
const sharingLabels: Record<string,string> = {'hard-cap':'Hard cap 2','sharing-4':'Share 2, ceiling 4','sharing-12':'Share 2, ceiling 12'};
const signalFixedDisabled=decisions.rows.find(r=>r.profile==='middleware-fixed'&&r.strategy==='disabled'&&r.phase==='pressure');
const signalFixedEnforce=decisions.rows.find(r=>r.profile==='middleware-fixed'&&r.strategy==='enforce'&&r.phase==='pressure');
const labels: Record<string, string> = {'direct':'Direct','proxy-fixed':'Proxy / fixed','proxy-adaptive':'Proxy / adaptive','middleware-fixed':'Middleware / fixed','middleware-adaptive':'Middleware / adaptive'};
export default function Benchmarks() {
  useEffect(()=>{document.getElementById(location.hash.split('/')[2]??'')?.scrollIntoView({behavior:'auto'});},[]);
  const [phase, setPhase] = useState('pressure');
  const [service, setService] = useState('orders');
  const [signalPhase,setSignalPhase]=useState('pressure');
  const [sharingPhase,setSharingPhase]=useState('returning');
  const phases = [...new Set(data.phases.map(row => row.phase))];
  const phaseNames: Record<string,string> = {baseline:'Normal traffic',ramp:'Traffic increases',pressure:'Database overload',burst:'Sudden traffic spike','intermittent-errors':'Database errors',recovery:'Recovery',sustained:'One minute of steady traffic','low-traffic':'Low traffic'};
  return <div className="container"><PageTitle title="Benchmarks">We run real services against PostgreSQL, stress their runtime and database work, and send more requests than the services can handle. These tests show which requests still finish, how long they take, and how many Gatewise rejects.</PageTitle>

    <Section id="choosing-a-policy" title="Start with the problem you need to solve">
      <p>The application has three services: orders, catalog and inventory. Each uses PostgreSQL through a four-connection pool. Checkout and background reports compete for those connections. Sending more requests does not create more database capacity; it can leave accepted work waiting so long that the client no longer benefits from it.</p>
      <p>A semaphore is a useful baseline because it directly bounds concurrent work with little policy. If that solves your workload, the measurements do not justify adding more controls. Gatewise becomes relevant when you also need to decide which work keeps access, react to changing capacity, or account for work below the HTTP boundary. The experiments below test those decisions separately.</p>
      <Table prose headers={['Problem in your service', 'Policy to evaluate', 'What you pay or must verify']} rows={[
        ['Similar requests compete for a stable resource budget.', 'Start with a semaphore or fixed unreserved admission.', 'Choose a measured ceiling. A low limit refuses useful work; a high one allows contention.'],
        ['Background traffic occupies capacity needed by checkout.', 'Priority reservations; compare both classes in the matched-traffic experiment.', 'Background work loses access to reserved capacity, even when critical traffic is idle.'],
        ['A dependency slows and the safe concurrency changes.', 'Adaptive feedback; compare against a fixed limit under slowdown and recovery.', 'Feedback is delayed. Targets, floors and ceilings still need tuning, and not every phase improves.'],
        ['Brief bursts could finish if they waited a little.', 'Bounded waiting; compare burst, sustained-overload and tight-deadline phases.', 'Waiting uses latency budget and memory. It does not increase execution capacity.'],
        ['One customer crowds out others, or hard caps leave capacity idle.', 'Tenant caps first; then shares and bounded borrowing if needed.', 'Caps reduce utilization. Borrowed work must drain before returning demand can use all its share.'],
        ['Jobs or database work continue independently of HTTP requests.', 'Separate worker and SQL admission, with relevant pool or standby signals.', 'Integrate at the real resource lifetime. HTTP metrics alone cannot prove SQL work has stopped.'],
      ]} />
      <p>Read <a href="#/benchmarks/hardening">the matched-traffic comparison</a> first for current policy tradeoffs, then follow the experiment for your question: <a href="#/benchmarks/queue">waiting</a>, <a href="#/benchmarks/adaptation">adaptation</a>, <a href="#/benchmarks/tenant-isolation">tenant isolation</a>, <a href="#/benchmarks/tenant-sharing">borrowing</a>, or <a href="#/benchmarks/operation-benchmarks">worker and SQL lifetimes</a>. The earlier periodic comparison remains available with its original failures and limitations. Release changes and upgrade notes live in <a href="#/versions">Versions</a>.</p>
    </Section>

    <Note label="Read success, latency and refusals together">A fast refusal is not a successful request. Many experiments count successes within a 100 ms goal, then report successful-request p95, refusals, errors and caller deadlines separately. A lower p95 can result from admitting fewer requests, so it is not enough on its own. Each experiment defines its timing boundary and workload; older reports do not all include generator scheduling delay. RPS means requests per second. These local experiments support comparisons within their documented setup, not a production-capacity promise.</Note>
    <p>We compare two ways to use Gatewise: middleware inside a Go service, and a proxy in front of a service. Fixed mode keeps the configured concurrency limit. Adaptive mode adjusts that limit within the bounds set by the operator.</p>
    <HardeningBenchmarks/>
    <ComparisonBenchmarks/>
    <QueueBenchmarks/>
    <AdaptationBenchmarks/>
    <PoolBalanceBenchmarks/>
    <OperationBenchmarks/>
    <ResourceBenchmarks/>
    <Section id="signal-engine" title="How should conflicting overload signals combine?">
 <h3>The problem</h3><p>Completed-request latency is useful feedback, but a service may know about resource pressure sooner. Several sources may disagree, or a source may stop responding. We need one predictable way to combine their advice while retaining existing hard limits.</p>
 <h3>What we run</h3><p>Orders, catalog and inventory use real PostgreSQL databases with four connections each. We compare signals disabled, observe mode and enforce mode, using fixed/adaptive middleware and proxy deployments. Observe records the same proposals while existing hard limits continue to apply. Each combination runs three times.</p><p>We start with healthy traffic, then add 40 ms SQL delay and send 600 requests/sec. A controlled source asks for a concurrency cap of 4. Next a second source requests rejection while the first reports healthy. We then fail the first source, whose configured fallback is a cap of 2, and finally restore healthy measurements and light traffic. These inputs test the engine; they do not detect actual database pressure.</p>
 <div className="evidence-strip"><div><strong>{decisions.sent.toLocaleString()}</strong><span>requests sent</span></div><div><strong>{decisions.runs}</strong><span>test runs</span></div><div><strong>{decisions.missed}</strong><span>missed scheduled requests</span></div><div><strong>{decisions.transport_errors}</strong><span>connection or transport errors</span></div></div>
 <h3>What happened</h3><p>For fixed middleware during pressure, successful work within 100 ms changed from {n(signalFixedDisabled?.timely_rps??null)} to {n(signalFixedEnforce?.timely_rps??null)} requests/sec. Successful p95 changed from {n(signalFixedDisabled?.p95_ms??null)} to {n(signalFixedEnforce?.p95_ms??null)} ms, while rejection changed from {n(signalFixedDisabled?.rejected_percent??null,2)}% to {n(signalFixedEnforce?.rejected_percent??null,2)}%. The table retains every deployment and mode. Observe records proposals without applying them. When one source requests rejection, a healthy reading from another source does not override it. When the source fails, the chosen fallback applies; healthy recovery removes that extra restriction.</p>
 <ImageFigure src="images/decision-pressure.png" alt="Measured successful requests within 100ms and SQL connection waiting for disabled, observe and enforce modes">Left: successful requests/sec within the test’s 100 ms goal during pressure. Right: average SQL-pool wait among acquisitions that waited. Each bar summarizes three runs. Check successful p95 and rejections below: a tighter cap can reduce waiting by turning requests away.</ImageFigure>
 <label className="metric-select"><span className="mono">SIGNAL PHASE</span><select aria-label="Signal benchmark phase" value={signalPhase} onChange={e=>setSignalPhase(e.target.value)}>{[['healthy','Healthy measurements'],['pressure','Pressure → cap 4'],['conflict','Conflicting sources → reject'],['unavailable','Source fails → fallback cap 2'],['recovery','Healthy recovery']].map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></label>
 <Table headers={['Deployment','Signal mode','All successes / sec','Within 100 ms / sec','Successful p95 · ms','Rejected · %','Server errors · %','Average SQL wait · ms']} rows={decisions.rows.filter(r=>r.phase===signalPhase).map(r=>[labels[r.profile],r.strategy,n(r.success_rps),n(r.timely_rps),n(r.p95_ms),n(r.rejected_percent,2),n(r.errors_percent,2),n(r.mean_wait_ms)])}/>
 <p>All {decisions.checks} checks passed. They cover request delivery, known outcomes, generator dispatch delay, connection cleanup, hard service bounds, signal rejection/caps, source-failure fallback and recovery. The Postman contract separately tests stale readings, explicit unknown state, errors, timeouts, mode ownership and unavailable public update routes. Go checks cover rapid changes, out-of-order/future observations, actor/resource scope, bounded stuck providers and concurrent limit changes.</p>
 <ImageFigure src="images/decision-trace.png" alt="Recorded adaptive baseline, admitted work, cached source state and database waiting through the signal test">One adaptive-proxy run for orders. The baseline belongs to the latency controller; the signal adds its own ceiling. The second source requests rejection during conflict. Unknown state follows source failure. These are sampled observations, so short transitions and request peaks can be missed.</ImageFigure>
 <details className="clone-placeholder"><summary>Setup, calculations, overhead and limits</summary><p>The workload is all critical: 60% orders, 20% catalog and 20% inventory. It uses scheduled arrivals with no retries, fresh databases for each run, 3s client deadlines and a 4096-request generator bound. Phases last 1–2 seconds, with 350 ms for signal delivery before counted traffic. This is a short local validation, not a production soak or a capacity forecast.</p><p>The primary threshold is 0.8, freshness 600 ms, pressure cap 4 and unknown cap 2. The secondary threshold is 0.8, with rejection under pressure and allow when unavailable. Polling is 100 ms with a 50 ms timeout. Both use service scope. The fixed baseline is 12; adaptive starts at 12 and stays between 5 and 12, independently of signal caps. Each service reserves 4 slots for critical work. All settings are test examples.</p>
 <p>Rates and successful p95 are medians of three run-level values. Rejection/error percentages pool the three runs’ counts. Average SQL wait divides total wait duration by acquisitions that waited; it is zero when no acquisition waited. No-success phases have no successful p95. Recovery is tested under light traffic and does not establish recovery time under sustained overload.</p>
 <Table headers={['Local Go microbenchmark','Median · ns/op','Range · ns/op','Bytes / op','Allocations / op']} rows={decisions.overhead.map(r=>[r.name.replace('Benchmark',''),n(r.ns_median,1),n(r.ns_min,1)+'–'+n(r.ns_max,1),String(r.bytes),String(r.allocs)])}/>
 <p>Cached evaluation benchmarks use 1, 8 or 32 healthy rules. Middleware benchmarks include a response recorder, an immediately completing handler and two healthy cached rules; disabled mode uses none. Three repetitions run on this host. These figures describe isolated code paths, including explanation/header costs, not end-to-end network latency or lock contention under many callers. Observation sampling never runs on this path.</p>
 <p>Controlled providers do not establish that an automatic memory, write or hot-key sensor will choose the right threshold. The v0.7.0 resource experiment above tests those providers and reservations separately. Scope caps compare shared service occupancy; they are not separate resource quotas. Local results do not establish cluster-wide fairness, production durability or a direct comparison with Cinnamon.</p>
 <CodeBlock filename="Reproduce · extracted demo" language="shell" code={"python3 decision_benchmark.py --output results/decision-results.json\n# In the included gatewise directory:\ngo test ./tests/decision -run '^$' -bench 'Benchmark(Evaluate|Middleware)$' -benchmem -count 3"}/>
 <p>Raw report SHA-256: <code>{decisions.source_sha256}</code>. Executable hashes, PostgreSQL image/version and measurement timestamps are in the report.</p></details>
 <div className="download-links"><a href="data/decision-results.json.gz" download>Complete report · gzip ↗</a><a href="data/decision-results.json" download>Report JSON ↗</a><a href="data/decision-overhead.txt" download>Microbenchmark output ↗</a><a href="data/decision-chart-provenance.json" download>Chart calculations ↗</a></div>
 </Section>
 <Section id="tenant-sharing" title="Can a busy customer borrow idle capacity safely?">
      <h3>The problem</h3><p>A hard cap can protect other customers but leave capacity unused while they are idle. In the earlier tenant test, a cap of 2 kept ordinary customers healthy but also limited the busy customer even when nobody else needed the room. This test asks whether lending can complete more work while preserving access for returning customers.</p>
      <h3>What we run</h3><p>First, one customer sends 480 requests/sec. Then three others return at 8 requests/sec each. Next all four become busy, the other customers leave again, and finally the database returns to normal. We compare the existing hard cap of 2 with a target share of 2 and total borrowing ceilings of 4 and 12. The database still has only four connections per service.</p>
      <div className="evidence-strip"><div><strong>{sharing.sent.toLocaleString()}</strong><span>requests sent</span></div><div><strong>{sharing.runs}</strong><span>test runs</span></div><div><strong>{sharing.missed}</strong><span>missed scheduled requests</span></div><div><strong>{sharing.transport_errors}</strong><span>connection or transport errors</span></div></div>
      <h3>What happened</h3><p>For fixed middleware, a ceiling of 4 increased solo throughput from about 115 to 231 successful requests/sec. Returning customers received 24 successful requests/sec within 100 ms in the median result, while their p95 range rose from about 46–50 ms to 68–73 ms. A ceiling of 12 completed more work overall, but some returning requests missed 100 ms or were rejected. The table shows the same tradeoff for each deployment.</p>
      <ImageFigure src="images/tenant-sharing.png" alt="Successful throughput with one customer and within-budget work for returning customers">Left: all successful requests/sec while just one customer is busy. Right: returning customers’ successful requests/sec within 100 ms; the dashed line is all 24 requests/sec they send. A policy can improve the left side while making the right side worse. Check the table for latency and rejections before choosing a ceiling.</ImageFigure>
      <h3>Read the tradeoff</h3><p>Borrowing lets a busy customer use more than its target share. It also allows more work to reach the database, so returning customers can wait behind requests already running. A ceiling of 4 means four total requests per tenant, including its share of 2; a ceiling of 12 permits substantially more competition. Neither the share nor the ceiling promises a response time.</p>
      <label className="metric-select"><span className="mono">TRAFFIC</span><select aria-label="Sharing benchmark phase" value={sharingPhase} onChange={e=>setSharingPhase(e.target.value)}>{[['solo','One busy customer'],['returning','Other customers return'],['all-busy','All customers busy'],['solo-again','Other customers leave'],['recovery','Healthy recovery']].map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></label>
      <Table headers={['Deployment','Tenant policy','All successes / sec','All within 100 ms / sec','Ordinary within 100 ms / sec','Ordinary p95 range · ms','Ordinary rejected · %','Ordinary server errors · %','First success for all ordinary callers · sec']} rows={sharing.rows.filter(r=>r.phase===sharingPhase).map(r=>[labels[r.profile],sharingLabels[r.strategy]??r.strategy,n(r.total_success_rps),n(r.total_timely_rps),r.ordinary_p95_range_ms.length?n(r.ordinary_timely_rps):'No ordinary traffic',r.ordinary_p95_range_ms.length?r.ordinary_p95_range_ms.map(v=>n(v)).join('–'):'—',r.ordinary_rejected_percent===null?'—':n(r.ordinary_rejected_percent,2),r.ordinary_errors_percent===null?'—':n(r.ordinary_errors_percent,2),r.first_all_returned_seconds===null?'—':n(r.first_all_returned_seconds,3)])} />
      <p>“First success” measures how long after the phase starts all three ordinary customers have received at least one successful response. It includes the wait until their first scheduled request. It shows restored access, not the time until every customer has its full target share or every request meets 100 ms. The p95 range keeps each ordinary-customer/run result visible.</p>
      <ImageFigure src="images/tenant-sharing-trace.png" alt="Recent tenant demand, borrowed reservations and adaptive limit during one experiment">One adaptive-proxy run with ceiling 12. As customers return, more shares count toward allocation. When they leave, idle demand expires and borrowing can grow again. Borrowed reservations keep the class assigned when acquired, even after other requests finish. They do not measure the current excess above a target. These are samples every 250 ms, so brief changes may be missed; Go tests separately check accounting and release rules.</ImageFigure>
      <h3>Returning while borrowed work is still running</h3><p>A separate live check starts returning customers while at least six borrowed requests are still active. With a 150 ms SQL delay and 16 busy clients, all four returning requests were admitted from their shares and completed in roughly 0.47–0.65 seconds across the four deployments. All 28 checks passed. The test clients retry 503 responses every 10 ms for up to 3 seconds; this is a handoff check, not the no-retry throughput benchmark.</p>
      <Note label="What this shows">These local experiments measure capacity use and access for returning customers. Existing requests are never interrupted, and a customer can still be rejected by service, priority or cohort rules below its tenant target. A longer demand window or lower ceiling can protect returning traffic more conservatively, at a cost to capacity use. Choose values using your database and request durations.</Note>
      <details className="clone-placeholder"><summary>Test setup and calculation details</summary><p>Four deployments × three policies × three repeats, with rotating execution order and fresh databases. Phases: 3s solo at 480 requests/sec; 5s returning traffic at 480 + 3×8/sec; 3s with each of four customers at 120/sec; 3s solo again at 480/sec; 3s recovery with each customer at 8/sec. SQL delay is 40 ms until recovery, then zero. All requests are critical and use the same 60% orders / 20% catalog / 20% inventory mix.</p><p>The scheduled phases run separately: responses and database work drain before the next phase starts. A separate live handoff check below keeps borrowed work running when customers return. Every service has a four-connection SQL pool, HTTP ceiling 12, critical reservation 4 and adaptive minimum 5. The tenant share/hard cap is 2. Borrowing ceilings are 4 or 12, demand window 500 ms, identity bound 32 and idle expiry 2s. Missing and overflow identities reject. The Go generator follows a schedule, never retries, allows 4,096 requests in flight and times out after 3s. Control calls and state sampling are outside measured business traffic.</p><p>All {sharing.checks} checks passed, covering request delivery, dispatch delay, returning-customer progress, registry bounds, service ceilings, connection cleanup and recovery. Sharing runs also check actual borrowing and its return when customers leave. Rates are medians across three runs, using each phase’s planned traffic duration, including requests that finish during drain. The 100 ms budget measures the HTTP round trip after dispatch; generator scheduling delay is recorded separately. Rejection percentages combine counts. The raw report includes per-tenant outcomes, pool waiting, sampled Go memory/goroutines and all checks. These are not CPU/RSS or multi-host capacity measurements.</p><p>Source report checksum: <code>{sharing.source_sha256}</code>.</p></details>
      <div className="download-links"><a href="data/sharing-results.json.gz" download>Full sharing results · gzip ↗</a><a href="data/sharing-chart-provenance.json" download>How the charts were calculated ↗</a><a href="data/sharing-validation.json" download>Live handoff check ↗</a></div>
      <CodeBlock filename="terminal · current demo" language="shell" code={'python3 sharing_benchmark.py --output results/sharing-results.json'} />
    </Section>
    <Section id="priority-chain" title="Keeping priority across services">
      <h3>The problem</h3><p>An urgent request can call another service and end up competing as ordinary background work. We want the receiving service to know how important that request is, while stopping callers from simply declaring themselves urgent.</p>
      <h3>What we run</h3><p>A request reaches the orders service, which calls catalog to read products from PostgreSQL. Catalog treats requests as batch work unless a trusted upstream supplies their priority. We send a mix of urgent, normal and batch requests, then slow catalog’s database reads and increase traffic. This lets us check both priority propagation and what each tier receives when capacity is scarce.</p>
      <div className="evidence-strip"><div><strong>{priority.sent.toLocaleString()}</strong><span>requests sent</span></div><div><strong>{priority.runs}</strong><span>test runs</span></div><div><strong>{priority.verified_successful_flows.toLocaleString()}</strong><span>successful calls checked</span></div><div><strong>{priority.cohort_mismatches}</strong><span>cohort mismatches within a rotation</span></div></div>
      <h3>What happened</h3><p>All {priority.verified_successful_flows.toLocaleString()} successful calls kept their priority from orders through catalog. Under database pressure, urgent requests had a higher percentage of successful responses within 100 ms than batch requests. Many requests were still rejected: priority decides which work gets access to limited capacity; it cannot make a slow database faster.</p>
      <ImageFigure src="images/priority-chain.png" alt="Successful requests within 100 ms and rejected requests, shown separately for each priority">The left charts show the percentage of each tier’s requests that succeeded within 100 ms. Higher is better. The right charts show the percentage rejected with HTTP 503. The top row uses a 40 ms database delay; the bottom row makes reads slower again, at 80 ms. Compare both sides to see the benefit and its cost.</ImageFigure>
      <Table headers={['Deployment / database delay','Priority','Succeeded within 100 ms / sec','Successful p95 · ms','Rejected · %','Other server errors · %']} rows={priority.rows.filter(r=>r.phase.includes('pressure')).map(r=>[labels[r.profile]+' / '+(r.phase==='downstream-pressure'?'40 ms':'80 ms'),r.tier,n(r.timely_rps),n(r.p95_ms),n(r.rejected_percent,2),n(r.other_5xx_percent,2)])} />
      <h3>What the cohort check means</h3><p>A cohort gives requests a repeatable preference within their priority tier. That preference changes periodically so the same users are not always favored. In this test, orders and catalog agreed on the cohort in all {priority.same_epoch_cohort_comparisons.toLocaleString()} successful comparisons made within the same rotation period. A call that crosses a rotation boundary can get a different bucket downstream. Services can also reject different requests because each has its own available capacity.</p>
      <p>We separately sent missing, malformed and forged priority headers while background requests were using the database. All 56 checks passed: missing priority used the route’s default, malformed values from trusted peers returned 400, and priority supplied at an untrusted entry returned 403. Fake Forwarded and X-Forwarded-For headers did not change that decision.</p>
      <Note label="What this shows">Request importance survives this service chain, and the tested trust rules hold under load. It does not guarantee that every urgent request succeeds or meets 100 ms. Cohort filtering can reject work before every slot is occupied, and rotation does not guarantee a maximum wait for a particular user. These measurements come from a local test, rather than a production deployment.</Note>
      <details className="clone-placeholder"><summary>Test setup and calculation details</summary>
        <p>We ran each of the four deployments three times, changing their execution order between repeats. Every run starts with 3 seconds at 60 requests/sec, then 8 seconds at 480 requests/sec with a 40 ms catalog SQL delay, then 6 seconds at 720 requests/sec with an 80 ms delay, and finally 4 seconds of recovery at 60 requests/sec. Traffic is 20% urgent, 20% normal and 60% batch.</p>
        <p>Each service has four SQL connections. Orders and inventory allow up to 12 concurrent requests; catalog allows 6. Two slots are reserved for urgent work and one additional slot for normal work. Adaptive mode cannot reduce the limit below 5. The demo uses three service processes and, in proxy mode, one shared Gatewise proxy. Only the isolated demo trusts localhost as an upstream.</p>
        <p>The test uses 64 artificial actor keys, 128 cohort buckets and a new rotation every 2 seconds. One extra request with a stable key checks rotation between traffic phases; it is excluded from the measured traffic. Same-period bucket comparisons exclude calls that cross a rotation boundary.</p>
        <p>The Go load generator sends requests on a schedule without waiting for earlier responses. It does not retry rejected requests. Its timeout is 3 seconds and it allows up to 4,096 requests in flight. No scheduled arrivals were missed and no connection or transport errors occurred. All {priority.checks} checks passed, including priority propagation, progress for every tier, connection cleanup and successful p95 below 100 ms during normal traffic and recovery.</p>
        <p>The useful-work bars show the median result from three runs. Rejection percentages combine request counts across those runs. Table p95 values are medians of each run’s p95, not a percentile calculated from all requests together. The separate header-validation test uses eight concurrent background clients and is not a capacity measurement.</p>
      <p>Report checksum: <code>{priority.sha256}</code>.</p></details>
      <div className="download-links"><a href="data/priority-results.json.gz" download>Download full priority results · gzip ↗</a><a href="data/priority-chart-provenance.json" download>How the charts were calculated ↗</a><a href="data/priority-validation.json" download>Priority-header validation results ↗</a></div>
      <CodeBlock filename="terminal · current demo" language="shell" code={'python3 priority_benchmark.py --output results/priority-results.json'} />
      <p>The tests below were recorded for earlier releases; their original results are kept for comparison.</p>
    </Section>
    <Section id="tenant-isolation" title="Protecting other customers from one busy caller">    <div className="evidence-strip"><div><strong>{tenants.sent.toLocaleString()}</strong><span>requests sent</span></div><div><strong>{tenants.runs}</strong><span>test runs</span></div><div><strong>{tenants.missed}</strong><span>missed scheduled requests</span></div><div><strong>{tenants.transport_errors}</strong><span>connection or transport errors</span></div></div>
      <h3>The problem</h3><p>A service-wide limit can stop overall overload, but one customer can still use most of the available slots. Other customers then get slow responses or rejections even though they send very little traffic.</p>
      <h3>What we run</h3><p>We send 480 requests/sec from one busy customer and 8 requests/sec from each of three other customers. Everyone uses the same operations and priority. We add 40 ms of database delay while each query holds one of the service’s four SQL connections. We then compare admission policies with and without per-customer limits.</p>
      <h3>What happened</h3><p>With tenant limits enabled, all three ordinary customers completed their combined 24 requests/sec within 100 ms in every tested deployment. Without tenant limits, the adaptive proxy completed about 12.1 of those requests/sec within the same budget. The busy customer was rejected more often when its cap was enforced.</p>
      <ImageFigure src="images/tenant-isolation.png" alt="How many ordinary-customer requests finish within 100 ms, alongside their rejection and error rates">The left bars show ordinary customers’ successful requests/sec within 100 ms. The dashed line is all 24 requests/sec they send. The right bars show how often those customers were rejected or received another server error. Tenant limits let them reach the dashed line in this test.</ImageFigure>
      <Table headers={['Policy', 'Ordinary callers: within 100 ms / sec', 'Ordinary callers: p95 range · ms', 'Ordinary callers: rejected · %', 'Ordinary callers: server errors · %', 'Busy caller: successes / sec', 'Busy caller: rejected · %', 'All callers: successes / sec']} rows={tenants.comparisons.map(row => [row.label,n(row.ordinary_timely_rps),row.ordinary_p95_range_ms.map(value=>n(value)).join('–'),n(row.ordinary_rejected_percent,3),n(row.ordinary_other_5xx_percent,3),n(row.noisy_success_rps),n(row.noisy_rejected_percent,3),n(row.total_success_rps)])} />
      <Note label="The cost of isolation">These are hard per-customer caps. A busy customer cannot borrow unused slots from someone else, so protecting ordinary customers also reduced total completed work. For example, the adaptive proxy completed about 272 requests/sec without tenant caps and 145 with them. This is a tradeoff between isolation and capacity use, not an overall throughput increase. The p95 range covers individual ordinary-customer/run results.</Note>
      <h3>When new identities keep arriving</h3><p>We also send requests with hundreds of new identities each second. Gatewise must keep its tracking table bounded instead of allocating an entry forever for every identity it sees. The next graph follows that table as traffic changes and shows it returning toward its normal size after inactive entries expire.</p>
      <ImageFigure src="images/tenant-tracking.png" alt="Recorded bounded tenant registry, tenant reservations and SQL pool waits">One adaptive-proxy run. The top chart shows stored tenant entries staying at or below the configured limit of 32 per service. The middle chart shows requests holding tenant slots; the bottom shows database-pool waits. We sample every 250 ms, so brief peaks may be missed; Go tests separately check that the accounting stays bounded.</ImageFigure>
      <details className="clone-placeholder"><summary>Test setup and calculation details</summary>
      <Table headers={['Setting', 'Experiment value']} rows={[
        ['Policies / repeats', 'No limiter, a basic fixed concurrency cap, and fixed/adaptive Gatewise proxy and middleware with tenant caps off/on. Ten variants, three repeats each; execution order changes between repeats.'],
        ['Phases', '3s normal traffic: four callers × 8 requests/sec. 12s overload: one caller sends 480/sec, others 8/sec each, with 40ms SQL delay. 4s of new identities at 400/sec, plus ordinary traffic. 4s recovery at the original rate.'],
        ['Application', 'Three services using PostgreSQL, with fresh databases for every run. Requests are 60% orders, 20% catalog and 20% inventory; all use critical priority.'],
        ['Service / tenant budgets', 'Service limit 12, critical reservation 4, adaptive minimum 5. Each tenant can run 2 requests at once. Track at most 32 identities; expire inactive entries after 2s. Missing identities and a full registry cause rejection.'],
        ['Plain semaphore', 'The basic semaphore allows 12 requests at once per service and rejects extra work immediately. It has no tenant rules. All measured traffic is critical, so the critical reservation does not change this comparison.'],
        ['Delivery / observation', 'Requests follow a schedule without waiting for earlier responses. The generator allows 4,096 in flight, times out after 3s and does not retry. Service state is sampled every 250ms.'],
      ]} />
      <p>All {tenants.checks} checks passed. They cover request delivery, monitoring, database connection cleanup and, when tenant limits are enabled, tracking bounds, rejection reasons, ordinary-customer progress and recovery. These results describe this local workload; limits apply separately to each Gatewise instance.</p>
      </details>
      <div className="download-links"><a href="data/tenant-results.json.gz" download>Complete tenant report · gzip ↗</a><a href="data/tenant-results.json" download>Report JSON ↗</a><a href="data/tenant-chart-provenance.json" download>How the charts were calculated ↗</a><a href="data/tenant-accounting-overhead.txt" download>Accounting microbenchmarks ↗</a></div>
      <details className="clone-placeholder"><summary>Internal accounting overhead and report checksum</summary><p>The accounting microbenchmark times only the internal work of checking and releasing tenant/service slots. It includes hashing and tracking, but excludes HTTP handling, authentication and metrics. Use it to inspect that small piece of overhead, rather than the cost of a complete request.</p><p>Report checksum: <code>{tenants.source_sha256}</code>. All customer identities in the experiment are artificial; Gatewise does not put individual identities into its metric labels.</p></details>
      <CodeBlock filename="terminal · current demo example" language="shell" code={'python3 tenant_benchmark.py --output results/tenant-results.json'} />
      <p>Every policy protects the same application and uses the same traffic generator. We have not benchmarked Cinnamon: the recorded <a href="data/cinnamon-availability.json" download>implementation search</a> did not identify an official public implementation we could use. A direct comparison remains pending access.</p>
    </Section>
    <Section id="recorded-results" title="Protecting important work when the database slows down">    <div className="evidence-strip"><div><strong>{data.sent.toLocaleString()}</strong><span>requests sent</span></div><div><strong>{data.run_count}</strong><span>independent deployment runs</span></div><div><strong>{data.dropped}</strong><span>missed scheduled arrivals</span></div><div><strong>{data.transport_errors}</strong><span>connection or transport errors</span></div></div>
<h3>The problem</h3><p>Checkout requests and background report jobs share the same database connections. When reports become expensive, important requests can spend most of their time waiting for a connection.</p>
      <h3>What we run</h3><p>Orders, catalog and inventory each have a four-connection database pool. We send 1,200 requests/sec across the services while slow report rebuilds compete with critical business requests. We compare no protection, a fixed limit and an adaptive limit, using both middleware and proxy deployments. Each test is repeated three times.</p>
      <h3>What happened</h3><p>In the overload phase, the adaptive proxy completed about 150 critical requests/sec within 100 ms, compared with about 43 for the fixed proxy. The graphs and table also show rejected requests and server errors, so the latency improvement can be assessed alongside its cost.</p>
      <ImageFigure src="images/commerce-critical.png" alt="Measured critical goodput and successful p95 under SQL overload">The throughput bars count critical requests that succeeded within 100 ms. The latency chart shows p95 for successful critical requests. Bars summarize three runs; dots show the individual results. Rejected and failed requests are counted separately in the table.</ImageFigure>
      <ImageFigure src="images/commerce-pool-outcomes.png" alt="SQL pool waiting alongside successful, rejected and failed business requests">The first chart shows time spent waiting for a database connection, across all three services and both priorities. The outcome chart separates successful, rejected and failed critical requests, using combined counts from the three overload runs.</ImageFigure>
      <p>The admission limit controls how much background work reaches the database. At the fixed limit of 12, up to 8 background reports can compete for only 4 database connections. When the adaptive limit falls to 5, the critical reservation leaves room for just one background request at a time. Fewer reports reach the connection pool, leaving critical work less competition. Gatewise controls HTTP admission; it does not reserve SQL connections or interrupt queries already running.</p>
      <div className="download-links"><a href="data/commerce-results.json.gz" download>Complete report · gzip ↗</a><a href="data/commerce-results.json" download>Report JSON ↗</a><a href="data/commerce-chart-provenance.json" download>How the charts were calculated ↗</a></div>
      <ImageFigure src="images/commerce-sustained.png" alt="Measured critical throughput and p95 during one minute of ordinary SQL traffic">We also send 1,500 requests/sec for one minute with no added database delay or errors. This checks ordinary operation as well as overload. The value of admission control depends on the workload; it need not improve throughput when a service is already healthy.</ImageFigure>
      <label className="metric-select"><span className="mono">PHASE</span><select aria-label="Benchmark phase" value={phase} onChange={event => setPhase(event.target.value)}>{phases.map(value => <option key={value} value={value}>{phaseNames[value] ?? value}</option>)}</select></label>
      <Table headers={['Deployment', 'Critical: within 100 ms / sec', 'Successful critical p95 · ms', 'Critical: rejected · %', 'Critical: server errors · %', 'Average database-pool wait · ms']} rows={data.phases.filter(row => row.phase === phase).map(row => [labels[row.deployment], n(row.critical_timely_per_second), n(row.critical_p95_ms), n(row.critical_rejected_percent,3), n(row.critical_backend_errors_percent,3), n(row.mean_pool_wait_ms)])} />
      <Note label="Read these together">A lower p95 can come from rejecting more requests. Check the number completed within 100 ms and the rejection rate together before deciding whether a policy helped. Server errors include non-503 5xx responses, including proxy errors. The p95 column summarizes each run’s successful-request p95. Database wait averages include only connection acquisitions that had to wait.</Note>
    </Section>
    <Section title="Service results"><p>Choose a service to see its overload results. Orders receives 60% of the traffic; catalog and inventory receive 20% each. Their request counts therefore differ even though each has its own admission limit and database pool.</p><Tabs label="Measured service" value={service} onChange={setService} options={[{value:'orders',label:'Orders'},{value:'catalog',label:'Catalog'},{value:'inventory',label:'Inventory'}]} />
      <Table headers={['Deployment', 'Critical: within 100 ms / sec', 'Successful p95 · ms', 'Rejected · %', 'Other server errors · %']} rows={data.service_comparisons.filter(row => row.service === service).map(row => [labels[row.deployment], n(row.timely_per_second), n(row.p95_ms), n(row.rejected_percent,3), n(row.backend_errors_percent,3)])} />
    </Section>
    <Section title="Controller validation"><p>The adaptive controller changes the concurrency limit using completed requests’ latency and errors. Here we check whether it reduces the limit during trouble and receives healthy feedback again after the faults are removed.</p><ImageFigure src="images/commerce-controller.png" alt="Measured limits, pool waits, latency feedback and error feedback for three service controllers">One adaptive-proxy run. Follow each service’s limit alongside database waiting, latency and errors as the test moves through overload and recovery. Each service learns from its own completed requests. Feedback is collected over time, so a value shown just after a phase change may still include requests from the preceding phase.</ImageFigure>
      <Table headers={['Deployment / service', 'Time until healthy feedback returns · sec', 'Final recovery limits · three runs']} rows={data.recovery.map(row => [labels[row.deployment]+' / '+row.service, n(row.median_healthy_feedback_seconds, 2), row.recovery_end_limits.join(' / ')])} />
      <p>The recovery time tells us when the controller first reports healthy feedback after faults are removed. Specifically, its estimated p90 is at most 80% of the configured latency target and the evaluated group has no failed samples. We check about every 250 ms, so this is an approximate observation. It is not a promise that every request has recovered by that instant. The limit grows only when there is evidence that more capacity is needed; it need not return to its maximum.</p>
      <p>All {data.checks} checks passed. We checked request delivery, concurrency bounds, database connections returning to the pool, recovery latency, low-traffic behavior and controller decisions. Go tests separately check error-driven changes, unchanged limits and old samples left over after an idle period.</p>
      <p>We also slowed the database gradually while keeping traffic at 600 requests/sec. Added SQL delay rose from 0 to 10, 20, 40 and 80 ms, followed by a traffic spike, database errors, recovery and low traffic. All {validation.checks} checks passed across {validation.runs} runs.</p>
      <Table headers={['Adaptive deployment', '80ms SQL delay: successful critical p95 · ms', 'Burst p95 · ms', 'Recovery p95 · ms']} rows={validation.profiles.map(row => [labels[row.deployment], n(row.pressure_p95_ms), n(row.burst_p95_ms), n(row.recovery_p95_ms)])} />
      <p>The 80 ms case shows why the configured minimum matters. The database has 4 connections, but Gatewise must still allow up to 5 concurrent requests at its minimum. Some work can therefore wait for a connection even after the controller has reduced the limit as far as allowed. The 100 ms target can still be missed. Improving that case requires revisiting the minimum and reservation, or increasing database capacity; the controller cannot go below the operator’s bound.</p><a className="text-link" href="data/controller-validation.json" download>Complete gradual-slowdown validation report ↗</a>
      <Note label="Controller behavior">This release kept the existing adjustment algorithm and added visibility into its decisions. The controller observes latency and errors; it does not diagnose every underlying cause. These results support the tested workloads, not a guarantee that adaptive mode improves every service.</Note>
    </Section>
    <Section title="Methodology"><p>The settings below apply to the v0.2.0 service-overload experiment. The priority and tenant experiments each list their own setup above. Every run starts with fresh databases; repeats use a different deployment order to reduce order effects.</p><details className="clone-placeholder"><summary>Hardware, traffic phases and measurement rules</summary><Table headers={['Parameter', 'Recorded setting']} rows={[
      ['Environment', `${data.platform} · ${data.hardware.cpu ?? 'see report'} · ${data.go_version}`],
      ['Host / database VM', `${data.hardware.host_logical_cpus} logical host CPUs, ${data.hardware.host_memory_bytes / 1024 ** 3} GiB RAM; PostgreSQL VM ${data.hardware.postgres_vm_resources.CPUs} CPUs, ${data.hardware.postgres_vm_resources.Memory / 1024} GiB RAM`],
      ['Database', `PostgreSQL ${data.postgres_version}; three fresh databases per run; 20,000 seeded rows each`],
      ['Order / repetitions', 'Five profiles × three repeats; rotating profile order; isolated databases and application processes'],
      ['Pool / admission per service', '4 SQL connections; max 12 admitted; reserved critical 4; adaptive min 5 / initial 12'],
      ['Feedback / deadlines', '500ms evaluation interval; 10 samples; 100ms target; 1s SQL deadline including pool wait; 3s client timeout'],
      ['Arrival model', 'Go open-loop schedule; 4,096 maximum in-flight generator requests; keep-alive; no application retries'],
      ['Normal mix', '60% orders / 20% catalog / 20% inventory; 80% business / 20% reports'],
      ['Overload mix', 'Same service proportions; 20% business / 80% reports'],
      ['Timing', `${data.started_at} → ${data.finished_at}`],
    ]} /><Table headers={['Phase', 'Duration', 'Total offered RPS', 'SQL conditions']} rows={[
      ['Baseline', '5s', '200', 'Real SQL; no injected delay/errors'],
      ['Ramp', '10s', '200 → 800, linear', '5× report work; explicit 10ms SQL delay'],
      ['Pressure', '15s', '1,200', '30× report work; explicit 40ms SQL delay'],
      ['Burst', '5s', '2,400', 'Same database degradation as pressure'],
      ['Intermittent errors', '10s', '800', 'Every fourth transaction fails via SQL division by zero; 5ms delay'],
      ['Recovery', '15s', '1,200', 'Faults removed; ordinary real SQL'],
      ['Sustained', '60s', '1,500', 'Ordinary real SQL; no injected delay/errors'],
      ['Low traffic', '5s', '10', 'Ordinary real SQL; no injected delay/errors'],
    ]} /><p>A report reads and aggregates its service’s data, then updates a report row. To simulate a slow dependency, we use PostgreSQL <code>pg_sleep</code> while the query holds a connection. Normal traffic, steady traffic, recovery and low-traffic phases have no added delay. Reports finish inside their HTTP handlers, so Gatewise holds their slots for the duration of that work. Database state carries over between phases of one run; completed writes can affect later costs. Each new run starts fresh. Proxy access logging stays enabled, monitoring containers stay off, and control/observation requests are excluded from the business-traffic counts.</p>
      <p>All {data.scheduled.toLocaleString()} scheduled requests are accounted for. To check the load generator itself, we measure the gap between a request’s scheduled time and when it was sent. The largest p95 gap for a service/priority group was {n(data.maximum_service_dispatch_p95_ms,2)} ms, below our 10 ms threshold. Completed requests/sec uses the planned phase duration. Successful p95 measures the HTTP round trip after sending; the raw report also includes time from the scheduled arrival and database cleanup after responses finish.</p>
      <p>Report checksum: <code>{data.source_sha256}</code>. The report also records binary checksums, the PostgreSQL image digest and runtime versions.</p></details>
    </Section>
    <Section title="Resources and limitations"><Table headers={['Deployment / service', 'Median sampled peak Go heap · MiB', 'Median sampled peak goroutines']} rows={data.resources.map(row => [labels[row.deployment]+' / '+row.service, n(row.median_peak_heap_mib), n(row.median_peak_goroutines,0)])} />
      <p>These figures come from periodically checking the backend Go processes. They show Go heap memory and goroutine counts, and can miss short peaks. They do not measure total process memory, CPU use or the proxy’s overhead. A one-minute run cannot establish long-term memory stability.</p><Note label="Scope">All tests run on one local computer, with PostgreSQL in a container VM. They show behavior under controlled overload, not how many requests a production deployment can safely serve. We have not established multi-host scaling, high availability or network-failure behavior here. The three services share a PostgreSQL instance; checkout is a separate operation, not a transaction across all services. Repeat the experiments with your workload before choosing limits.</Note>
      <p>We test overload and recovery because a limiter can look healthy at low traffic and still fail when demand exceeds capacity. For more background, see <a href="https://aws.amazon.com/builders-library/using-load-shedding-to-avoid-overload/" target="_blank" rel="noreferrer">AWS Builders’ Library on load shedding</a> and <a href="https://www.envoyproxy.io/docs/envoy/latest/configuration/http/http_filters/adaptive_concurrency_filter" target="_blank" rel="noreferrer">Envoy’s adaptive-concurrency documentation</a> on overload behavior and how controllers collect feedback.</p>
    </Section>
    <Section title="Reproduction"><p>To reproduce the original v0.2.0 experiment, download its matching demo from <a href="#/versions">Versions</a>. The current demo also includes this test sequence. Priority and tenant reproduction commands are included in their sections above.</p><CodeBlock filename="terminal · extracted gatewise-demo" language="shell" code={`python3 benchmark.py --output results/commerce-results.json\npython3 validate_controller.py --output results/controller-validation.json\n# Optional metrics view; run separately from measurements:\npython3 run.py --profile proxy-adaptive --monitor`} /><Button href="#/examples" secondary>Download source and Postman example</Button></Section>
  </div>;
}
